// WorkspaceServiceHandler is an implementation of the toshi.workspace.v1.WorkspaceService service.
type WorkspaceServiceHandler interface {
	// GetWorkspace returns the caller's workspace.
	GetWorkspace(context.Context, *connect.Request[workspacev1.GetWorkspaceRequest]) (*connect.Response[workspacev1.GetWorkspaceResponse], error)
	// UpdateWorkspace changes the fields of the caller's workspace that
	// update_mask names and returns the workspace as stored. The paths are
	// "name" and "settings.<field>" for a field of WorkspaceSettings. An
	// omitted update_mask means the fields the request populates, an empty
	// one changes nothing, and "*" or another path fails with
	// INVALID_ARGUMENT. The call needs no permission of its own: each path
	// needs its field group's, workspace.signin for settings.sign_in,
	// billing.write for the spending limits and workspace.write for the
	// others, and a mask that names nothing needs any one of them. A caller
	// that lacks one is refused with PERMISSION_DENIED naming it, and nothing
	// is written.
	//
	// The workspace's settings are checked as a whole after the change, and a
	// value they refuse fails with INVALID_ARGUMENT; the fields the mask names
	// are also checked against the plan and the caller, as their
	// descriptions say. A workspace.etag that differs from the workspace's
	// fails with ABORTED and changes nothing; without one the last write wins.
	UpdateWorkspace(context.Context, *connect.Request[workspacev1.UpdateWorkspaceRequest]) (*connect.Response[workspacev1.UpdateWorkspaceResponse], error)
	// ListWorkspaces returns the workspaces of the caller, ordered by ID: a
	// session's workspaces, or a token's one.
	//
	// A page holds 100 workspaces when page_size is zero, and 1000 at most.
	ListWorkspaces(context.Context, *connect.Request[workspacev1.ListWorkspacesRequest]) (*connect.Response[workspacev1.ListWorkspacesResponse], error)
	// GetWorkspaceBilling returns the workspace's billing customer,
	// subscription and its status, the usage reported to the billing provider
	// per month and runner size, and the events that failed. months outside
	// 0 to 12 fails with INVALID_ARGUMENT.
	GetWorkspaceBilling(context.Context, *connect.Request[workspacev1.GetWorkspaceBillingRequest]) (*connect.Response[workspacev1.GetWorkspaceBillingResponse], error)
	// GetWorkspaceStatement returns the workspace's usage statement for one
	// UTC month: minutes by runner size and OS of the jobs that finished in
	// it, the minutes metered to the billing provider by size with their
	// estimated cost at the plan's prices, the starter credit applied in it,
	// and held time by reason. A month not in YYYY-MM form fails with
	// INVALID_ARGUMENT.
	GetWorkspaceStatement(context.Context, *connect.Request[workspacev1.GetWorkspaceStatementRequest]) (*connect.Response[workspacev1.GetWorkspaceStatementResponse], error)
	// ListSeats returns the desktop seats the workspace held in one UTC
	// month, oldest assigned first: the seats live at some time in it,
	// removed ones included. A person assigned a seat may open a display on
	// Windows that Toshi licenses; each seat is billed for every month it
	// touches. A month not in YYYY-MM form fails with INVALID_ARGUMENT.
	ListSeats(context.Context, *connect.Request[workspacev1.ListSeatsRequest]) (*connect.Response[workspacev1.ListSeatsResponse], error)
	// AssignSeat assigns a desktop seat to a member of the workspace. A
	// person who holds a live seat fails with ALREADY_EXISTS, and one who is
	// not a member with NOT_FOUND. A seat removed this month stays billed for
	// it, so assigning a seat to another person in its place is a second
	// seat.
	AssignSeat(context.Context, *connect.Request[workspacev1.AssignSeatRequest]) (*connect.Response[workspacev1.AssignSeatResponse], error)
	// RemoveSeat removes a live seat: its person may open no display on
	// Windows that Toshi licenses from then on, and the seat stays billed for
	// the months it touched. A seat the workspace does not have, or one
	// already removed, fails with NOT_FOUND. A member's removal from the
	// workspace removes their seat too.
	RemoveSeat(context.Context, *connect.Request[workspacev1.RemoveSeatRequest]) (*connect.Response[workspacev1.RemoveSeatResponse], error)
	// ListEgressIPs returns the public addresses the workspace's jobs may
	// reach the internet from: the egress addresses of the hosts its jobs can
	// land on, its own hosts and, unless it runs on its own hosts only, the
	// shared hosts its plan's operating systems run on.
	//
	// A page holds 100 hosts when page_size is zero, and 1000 at most.
	ListEgressIPs(context.Context, *connect.Request[workspacev1.ListEgressIPsRequest]) (*connect.Response[workspacev1.ListEgressIPsResponse], error)
	// GetUsage returns the workspace's job counts and billable minutes per UTC
	// day, conclusion, outcome and kind, for the jobs whose queued_at is in
	// the window. The window defaults to the last 7 days. A window whose from
	// is not before its to fails with INVALID_ARGUMENT.
	GetUsage(context.Context, *connect.Request[workspacev1.GetUsageRequest]) (*connect.Response[workspacev1.GetUsageResponse], error)
	// GetQueueTimes returns a queue-time summary (percentiles, maximum and
	// warm share) for the workspace's jobs that reached running in the
	// window, where a job is in the window by its queued_at. The window
	// defaults to the last 7 days. A window whose from is not before its to
	// fails with INVALID_ARGUMENT.
	GetQueueTimes(context.Context, *connect.Request[workspacev1.GetQueueTimesRequest]) (*connect.Response[workspacev1.GetQueueTimesResponse], error)
	// GetWorkflowUsage returns, per repository and workflow name, the jobs
	// GetUsage counts: their billable minutes, failed jobs and run-time
	// percentiles. A job is in the window by its queued_at. The window
	// defaults to the last 7 days. A window whose from is not before its to
	// fails with INVALID_ARGUMENT.
	GetWorkflowUsage(context.Context, *connect.Request[workspacev1.GetWorkflowUsageRequest]) (*connect.Response[workspacev1.GetWorkflowUsageResponse], error)
	// ListPlans returns the configured plans sorted by name.
	//
	// A page holds 100 plans when page_size is zero, and 1000 at most.
	ListPlans(context.Context, *connect.Request[workspacev1.ListPlansRequest]) (*connect.Response[workspacev1.ListPlansResponse], error)
	// CreateCheckoutSession returns a Stripe Checkout URL that subscribes the
	// workspace to plan, first creating and linking a billing customer for a
	// workspace without one. An empty plan, a plan the configuration does not
	// define, or a return_url outside the allowed origins fails with
	// INVALID_ARGUMENT; self-serve billing off, a plan that is not sold or
	// maps to several lookup keys, a price missing in Stripe, or a workspace
	// that already has a subscription fails with FAILED_PRECONDITION; a
	// billing provider failure fails with UNAVAILABLE.
	CreateCheckoutSession(context.Context, *connect.Request[workspacev1.CreateCheckoutSessionRequest]) (*connect.Response[workspacev1.CreateCheckoutSessionResponse], error)
	// CreateBillingPortalSession returns a Stripe Customer Portal URL where
	// the workspace manages its card and subscription. A return_url outside
	// the allowed origins fails with INVALID_ARGUMENT; self-serve billing not
	// configured, or a workspace with no billing customer, fails with
	// FAILED_PRECONDITION; a billing provider failure fails with UNAVAILABLE.
	CreateBillingPortalSession(context.Context, *connect.Request[workspacev1.CreateBillingPortalSessionRequest]) (*connect.Response[workspacev1.CreateBillingPortalSessionResponse], error)
	// GetVersion returns the control plane's version, commit and commit
	// date, and the oldest agent release it admits.
	GetVersion(context.Context, *connect.Request[workspacev1.GetVersionRequest]) (*connect.Response[workspacev1.GetVersionResponse], error)
	// DeleteWorkspace schedules the caller's workspace's deletion: the
	// workspace is suspended until purge_after, the deployment's default
	// grace from now, after which its data is purged from the control plane
	// and every host. confirm must equal the workspace's name as
	// GetWorkspace returns it, else the call fails with INVALID_ARGUMENT. A
	// workspace that is not active (suspended, deletion scheduled, deleting or
	// deleted) fails with FAILED_PRECONDITION, with the state as the
	// google.rpc.ErrorInfo reason. The answer carries the workspace with
	// purge_after and deletion_by "owner".
	DeleteWorkspace(context.Context, *connect.Request[workspacev1.DeleteWorkspaceRequest]) (*connect.Response[workspacev1.DeleteWorkspaceResponse], error)
	// CancelWorkspaceDeletion cancels a deletion an Owner scheduled while its
	// purge_after is in the future, and returns the workspace to active; held
	// jobs run at the next scheduler pass. It is the one call other than the
	// reads a workspace with a scheduled deletion takes. A workspace with no
	// scheduled deletion, one the operator scheduled, or one whose
	// purge_after has passed fails with FAILED_PRECONDITION, with the reason
	// in a google.rpc.ErrorInfo.
	CancelWorkspaceDeletion(context.Context, *connect.Request[workspacev1.CancelWorkspaceDeletionRequest]) (*connect.Response[workspacev1.CancelWorkspaceDeletionResponse], error)
}

